package com.example.parcel.app.parcel;

import com.example.parcel.application.parcel.RegisterParcel;
import com.example.parcel.domain.parcel.ParcelId;
import jakarta.inject.Inject;
import jakarta.ws.rs.Consumes;
import jakarta.ws.rs.POST;
import jakarta.ws.rs.Path;
import jakarta.ws.rs.core.MediaType;
import jakarta.ws.rs.core.Response;

@Path("/parcels")
public class ParcelResource {
    @Inject
    RegisterParcel registerParcel;

    @POST
    @Consumes(MediaType.APPLICATION_JSON)
    public Response register(RegisterParcelRequest request) {
        if (request == null) {
            throw new IllegalArgumentException("body is required");
        }
        registerParcel.execute(new ParcelId(request.parcelId()), request.weightKg());
        return Response.status(Response.Status.CREATED).build();
    }
}
